(2500250, 344424, 12857, '<td valign="top">Green but no wow factor or impact....</td>', 'Green but no wow factor or impact....', '2006-06-08 22:16:45.000000', NULL, 1),
(2500251, 343511, 12857, '<td valign="top">I really like this .... I wish you had captured the shot before the snail messed it up with his sludge trail.  Easy to fix with a little clone stamp.  i know you could not do it for this challenge and and I did not hold it against you.  Great job and for me a 10.  Great focus and original idea.  Keep up the good work.............</td>', 'I really like this .... I wish you had captured the shot before the snail messed it up with his sludge trail.  Easy to fix with a little clone stamp.  i know you could not do it for this challenge and and I did not hold it against you.  Great job and for me a 10.  Great focus and original idea.  Keep up the good work.............', '2006-06-08 22:19:41.000000', NULL, 1),
(2500254, 341305, 12857, '<td valign="top">Not sharp.....</td>', 'Not sharp.....', '2006-06-08 22:22:14.000000', NULL, 1),
(2500258, 343096, 12857, '<td valign="top">Cool idea,  Great title.  Beautiful exposure.  Have to score you well above average.<br/>dc</td>', 'Cool idea,  Great title.  Beautiful exposure.  Have to score you well above average.dc', '2006-06-08 22:23:56.000000', NULL, 1),
