(2505984, 344045, 48339, '<td valign="top">nice it''s.</td>', 'nice it''s.', '2006-06-11 01:59:19.000000', NULL, 1),
(2505988, 344369, 56673, '<td valign="top">Majestic indeed.  Great reflection in the water.  Seems almost too green - maybe the color was tweaked just a little bit too much?</td>', 'Majestic indeed.  Great reflection in the water.  Seems almost too green - maybe the color was tweaked just a little bit too much?', '2006-06-11 02:00:22.000000', NULL, 1),
(2505994, 344469, 56673, '<td valign="top">They look like beady little eyes!</td>', 'They look like beady little eyes!', '2006-06-11 02:01:58.000000', NULL, 1),
(2505999, 344187, 56673, '<td valign="top">Beautiful shot with such a simple subject.  Nice the way the curves are working together, and the colors work nicely too.  The cropping is excellent.</td>', 'Beautiful shot with such a simple subject.  Nice the way the curves are working together, and the colors work nicely too.  The cropping is excellent.', '2006-06-11 02:04:20.000000', NULL, 1),
(2506002, 343809, 56673, '<td valign="top">Congratulations to the graduate!</td>', 'Congratulations to the graduate!', '2006-06-11 02:05:17.000000', NULL, 1),
(2506005, 343488, 56673, '<td valign="top">Neat idea.  The arrowhead really adds some interest.</td>', 'Neat idea.  The arrowhead really adds some interest.', '2006-06-11 02:06:40.000000', NULL, 1),
