(2506047, 343428, 56673, '<td valign="top">This was one idea I had.  Glad I didn''t shoot it though - mine wouldn''t have been as good.</td>', 'This was one idea I had.  Glad I didn''t shoot it though - mine wouldn''t have been as good.', '2006-06-11 02:20:37.000000', NULL, 1),
(2506051, 342615, 48339, '<td valign="top">i feel like there could be some dodging and burning on this one.</td>', 'i feel like there could be some dodging and burning on this one.', '2006-06-11 02:22:48.000000', NULL, 1),
(2506053, 344350, 56673, '<td valign="top">Too much green?  Looks overprocessed to me.</td>', 'Too much green?  Looks overprocessed to me.', '2006-06-11 02:24:46.000000', NULL, 1),
