INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2506335, 344243, 9668, '<td valign="top">Nice photo. Wish the lighting was a little more dynamic.</td>', 'Nice photo. Wish the lighting was a little more dynamic.', '2006-06-11 08:34:00.000000', NULL, 1),
(2506336, 344328, 9668, '<td valign="top">Looks like it was taken under a microscope! Very cool effect.</td>', 'Looks like it was taken under a microscope! Very cool effect.', '2006-06-11 08:35:19.000000', NULL, 1),
(2506346, 343751, 40005, '<td valign="top">green is really too dark, because of the back light.</td>', 'green is really too dark, because of the back light.', '2006-06-11 08:50:09.000000', NULL, 1),
(2506361, 342720, 29535, '<td valign="top">That''s such an awesome photo, but everything is brown or blue.  Sorry but this doesn''t fit the challenge IMO.</td>', 'That''s such an awesome photo, but everything is brown or blue.  Sorry but this doesn''t fit the challenge IMO.', '2006-06-11 09:11:00.000000', NULL, 1),
(2506366, 344417, 40005, '<td valign="top">simple and efficient, great shot !</td>', 'simple and efficient, great shot !', '2006-06-11 09:13:12.000000', NULL, 1),
(2506370, 343901, 40005, '<td valign="top">I find that background is a little blown out, but it''s a nice natural architecture</td>', 'I find that background is a little blown out, but it''s a nice natural architecture', '2006-06-11 09:17:17.000000', NULL, 1),
(2506375, 343942, 40005, '<td valign="top">nice sharpness and great shades of green</td>', 'nice sharpness and great shades of green', '2006-06-11 09:21:58.000000', NULL, 1),
(2506397, 342802, 40005, '<td valign="top">I love this deep green !</td>', 'I love this deep green !', '2006-06-11 09:46:11.000000', NULL, 1),
(2506408, 343996, 40005, '<td valign="top">nice portrait ;)</td>', 'nice portrait ;)', '2006-06-11 09:51:43.000000', NULL, 1),
(2506416, 342392, 40005, '<td valign="top">nice details and bright green, I love this shot</td>', 'nice details and bright green, I love this shot', '2006-06-11 09:56:16.000000', NULL, 1),
(2506431, 344357, 58947, '<td valign="top">I''m a sucker for boats and water shots. I love the saturated blues and greens, the perfect still of the water, the crop, the shadows, and the temperature. Beautiful. :-)</td>', 'I''m a sucker for boats and water shots. I love the saturated blues and greens, the perfect still of the water, the crop, the shadows, and the temperature. Beautiful. :-)', '2006-06-11 10:01:41.000000', NULL, 1),
(2506470, 344404, 58947, '<td valign="top">I''m completely in love with these lush abstracts. I like the lines, curves, colours, the painterly feel to them. I''m 100% certain I know who''s image this is, and if I''m correct I can only say this is a wonderful addition to a series that I would happily display on my wall. <br/> <br/>My only nit is that I think the L shaped, light green bit in the lower left side would look better if it were more in focus. <br/> <br/>A very nice image.</td>', 'I''m completely in love with these lush abstracts. I like the lines, curves, colours, the painterly feel to them. I''m 100% certain I know who''s image this is, and if I''m correct I can only say this is a wonderful addition to a series that I would happily display on my wall.  My only nit is that I think the L shaped, light green bit in the lower left side would look better if it were more in focus.  A very nice image.', '2006-06-11 10:38:44.000000', NULL, 1),
(2506498, 341759, 15204, '<td valign="top">A well seen shot and excellent exposure.  I think a little more contrast would really mae the colors pop on this shot.  (A minor nitpick, too, your horizon is not completely level)</td>', 'A well seen shot and excellent exposure.  I think a little more contrast would really mae the colors pop on this shot.  (A minor nitpick, too, your horizon is not completely level)', '2006-06-11 11:01:44.000000', NULL, 1),
(2506501, 343518, 35530, '<td valign="top">Nice composition. The only thing that detracts is the lighting.</td>', 'Nice composition. The only thing that detracts is the lighting.', '2006-06-11 11:04:12.000000', NULL, 1),
(2506504, 342693, 35530, '<td valign="top">Gorgeous.</td>', 'Gorgeous.', '2006-06-11 11:05:06.000000', NULL, 1),
(2506510, 343359, 15204, '<td valign="top">I love the blurred background, but I think that it would have been better to have enough DOF to have his cute little feet in focus, too.  CUte shot. I like the texture of the sand (on the beach and on him :)</td>', 'I love the blurred background, but I think that it would have been better to have enough DOF to have his cute little feet in focus, too.  CUte shot. I like the texture of the sand (on the beach and on him :)', '2006-06-11 11:11:11.000000', NULL, 1),
(2506516, 344050, 9668, '<td valign="top">1954 was before my parents were even born! Nice layers of green.</td>', '1954 was before my parents were even born! Nice layers of green.', '2006-06-11 11:17:27.000000', NULL, 1),
(2506522, 344481, 9668, '<td valign="top">"G" - I like the title even though I don''t understand it =).<br/>Lovely photo, nice simple yet effective composition, and great soft lighting.<br/>A-pear-antly I''m bananas about your photo!</td>', '"G" - I like the title even though I don''t understand it =).Lovely photo, nice simple yet effective composition, and great soft lighting.A-pear-antly I''m bananas about your photo!', '2006-06-11 11:21:10.000000', NULL, 1),
(2506524, 343882, 9668, '<td valign="top">The color look blue to me. Like the fading corridor though.</td>', 'The color look blue to me. Like the fading corridor though.', '2006-06-11 11:23:01.000000', NULL, 1),
(2506526, 342121, 9668, '<td valign="top">Nice lighting. Looks like the camera might have been shaking when you took the photo because it looks a bit blurry. Cool framing through the leaves. <br/>Cousin?</td>', 'Nice lighting. Looks like the camera might have been shaking when you took the photo because it looks a bit blurry. Cool framing through the leaves. Cousin?', '2006-06-11 11:24:54.000000', NULL, 1),
(2506531, 344494, 9668, '<td valign="top">Lovely concept and excellent execution. Love it.</td>', 'Lovely concept and excellent execution. Love it.', '2006-06-11 11:28:26.000000', NULL, 1),
(2506532, 344000, 9668, '<td valign="top">Love the variety of textures.</td>', 'Love the variety of textures.', '2006-06-11 11:29:01.000000', NULL, 1),
