INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2514613, 344412, 9668, '<td valign="top">Congrats on the blue ribbon! Awesome photo! Funny story to go along with it too =)</td>', 'Congrats on the blue ribbon! Awesome photo! Funny story to go along with it too =)', '2006-06-14 01:16:32.000000', NULL, 0),
